"""Build the names-fix plan rows (items 3-5 of the 2026-10-03 audit) from explicit, reviewed decisions.
Usage: python3 scratch/names_fix.py index.tsv out.tsv quarantine_out.tsv"""
import csv, re, sys
idx = {p: int(s) for p, s in csv.reader(open(sys.argv[1]), delimiter='\t')}
rows, quar = [], []
def mv(a, b, why):
    assert a in idx, a
    assert len(b.split('/')[-1].encode()) <= 200 and all(len(x.encode()) <= 200 for x in b.split('/')), b
    rows.append(('Books/' + a, 'Books/' + b, why))
def mvdir(a, b, why):   # rename a folder = move each file (apply_plan removes the emptied folder)
    fs = [p for p in idx if p.startswith(a + '/')]
    assert fs, a
    for p in fs: mv(p, b + p[len(a):], why)
    return fs

