mv(S + '01 - سير أعلام النبلاء ((ت الأرناؤوط - الرسالة) - السيرة...).pdf', S + 'سير أعلام النبلاء (السيرة النبوية 1).pdf', '"..." removed; archive.org file sansera1 = السيرة النبوية 1 (companion, no number)')
mv(S + '01 - سير أعلام النبلاء ((ت الأرناؤوط - الرسالة) - السيرة...) (نسخة أخرى).pdf', S + 'سير أعلام النبلاء (السيرة النبوية 2).pdf', '"..." removed; archive.org file sansera2 = السيرة النبوية 2')
mv(S + '01 - سير أعلام النبلاء ((ت الأرناؤوط - الرسالة) - سيرة ا...).pdf', S + 'سير أعلام النبلاء (سيرة الخلفاء الراشدين).pdf', '"..." removed; archive.org file sankholfa = سيرة الخلفاء الراشدين')
# _alt: a second, different preface file beside "(المقدمة)" → «(المقدمة - نسخة أخرى)»; a 13-byte stub → quarantine
alts = [p for p in idx if '_alt' in p]
for p in alts:
    if idx[p] < 20480: quar.append((p, 'stub file (%d bytes) named _alt' % idx[p])); continue
    twin = p.replace('_alt', '')
    if twin in idx and idx[twin] == idx[p]: quar.append((p, 'same size as ' + twin)); continue
    mv(p, p.replace(' (المقدمة)_alt.pdf', ' (المقدمة - نسخة أخرى).pdf'), '_alt → (نسخة أخرى): different size from the main preface')
# نسخة ثانية: §4 says it is a duplicate → quarantine for review
for p in [p for p in idx if 'نسخة ثانية' in p]:
    sib = [q for q in idx if q.rsplit('/', 1)[0] == p.rsplit('/', 1)[0] and q != p]
    if sib: quar.append((p, '(نسخة ثانية) beside ' + sib[0].rsplit('/', 1)[1] + ' — sizes differ, other edition/scan? review'))
    else: mv(p, p.replace(' (نسخة ثانية)', ''), '(نسخة ثانية) removed: the only file of its folder')
F = 'الأدب/نقد الشعر - قدامة بن جعفر/'
quar.append((F + 'نقد الشعر - قدامة بن جعفر.pdf', '4868-byte stub (not the book)'))
mv(F + 'نقد الشعر  - قدامة بن جعفر.pdf', F + 'نقد الشعر.pdf', 'double space; the stub of the same name goes to review')

